/tmp/walk_probe_logger.sh.content:
#!/bin/sh
{
  printf 'ARGV:'
  for arg in "$@"; do
    printf ' [%s]' "$arg"
  done
  printf '\n'
  printf 'PWD: [%s]\n' "$PWD"
} >> /tmp/walk_probe_logger.out
exit 0

